<script src="js/public-account-menu.js"></script><script>
(async()=>{const form=document.getElementById('cateringForm'),button=document.getElementById('submitButton'),message=document.getElementById('formMessage');const show=(text,bad=false)=>{message.textContent=text;message.className='message '+(bad?'bad':'good')};
try{const r=await fetch('api/public-brand.php',{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(d.brand){const b=d.brand;document.documentElement.style.setProperty('--accent',b.primary||'#d94a2b');document.getElementById('brandName').textContent=b.restaurantName||'Restaurant';const logo=document.getElementById('brandLogo');if(b.logoUrl){const img=document.createElement('img');img.src=b.logoUrl;img.alt='';logo.replaceChildren(img)}else logo.textContent=b.logoText||'G';document.title=`Catering · ${b.restaurantName||'Restaurant'}`}}catch{}
form.addEventListener('submit',async event=>{event.preventDefault();message.className='message hidden';if(!form.reportValidity())return;button.disabled=true;button.textContent='Submitting…';const id=x=>document.getElementById(x);const payload={csrf_token:id('csrf').value,website_check:id('website_check').value,companyName:id('companyName').value.trim(),contactName:id('contactName').value.trim(),email:id('email').value.trim(),phone:id('phone').value.trim(),eventType:id('eventType').value,eventDate:id('eventDate').value,startTime:id('startTime').value,endTime:id('endTime').value,guestCount:id('guestCount').value,venueName:id('venueName').value.trim(),venueAddress:id('venueAddress').value.trim(),serviceStyle:id('serviceStyle').value,menuInterests:id('menuInterests').value.trim(),dietaryRequirements:id('dietaryRequirements').value.trim(),beverageService:id('beverageService').value,staffingNeeds:id('staffingNeeds').value,rentalsNeeds:id('rentalsNeeds').value.trim(),budgetRange:id('budgetRange').value,fulfillmentPreference:id('fulfillmentPreference').value,notes:id('notes').value.trim(),consent:id('consent').checked};try{const r=await fetch('api/public-catering.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':payload.csrf_token},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Could not submit the catering request.');show(d.message||'Catering request received.');form.reset();window.scrollTo({top:document.querySelector('.wrap').offsetTop-20,behavior:'smooth'})}catch(error){show(error.message||'Could not submit the catering request.',true)}finally{button.disabled=false;button.textContent='Submit catering request'}})})();
</script></body></html>